package com.keyforge.nativeiiq.source;
import com.keyforge.nativeiiq.config.NativeExtractionConfig; import com.keyforge.nativeiiq.model.*; import sailpoint.api.SailPointContext; import sailpoint.object.*; import sailpoint.tools.GeneralException; import java.time.Instant; import java.util.*;
/** Uses the forward native Identity.getWorkgroups() relationship; page coordinates count Identity source objects. */
public final class NativeWorkgroupMembershipExtractor { private final SailPointContext c;private final NativeExtractionConfig config;public NativeWorkgroupMembershipExtractor(SailPointContext c,NativeExtractionConfig n){this.c=c;config=n;} public NativeWorkgroupMembershipExtractionResult extract(int start,int limit)throws GeneralException{QueryOptions q=new QueryOptions();q.addOrdering("name",true);q.addOrdering("id",true);q.setFirstRow(Math.max(0,start));if(limit>0)q.setResultLimit(limit);Iterator<Object[]>it=c.search(Identity.class,q,"id");List<String>ids=new ArrayList<>();while(it!=null&&it.hasNext())ids.add((String)it.next()[0]);boolean done=limit<=0||ids.size()<limit;int next=start+ids.size();NativeWorkgroupMembershipExtractionResult out=new NativeWorkgroupMembershipExtractionResult(config.getSourceSystem(),config.getExtractionRunId(),start,ids.size(),next,done);for(String id:ids){Identity member=c.getObjectById(Identity.class,id);if(member==null)continue;try{List<Identity>wgs=member.getWorkgroups();if(wgs==null)continue;for(Identity wg:wgs){if(wg==null||wg.getId()==null)continue;NativeWorkgroupMembershipRow r=new NativeWorkgroupMembershipRow();r.setWorkgroupId(wg.getId());r.setWorkgroupName(wg.getName());r.setIdentityId(member.getId());r.setIdentityName(member.getName());r.setFirstName(member.getFirstname());r.setLastName(member.getLastname());r.setMemberIsWorkgroup(Boolean.valueOf(member.isWorkgroup()));r.setSrcSystem(config.getSourceSystem());r.setRunId(config.getExtractionRunId());r.setExtractedAt(Instant.now());out.getRows().add(r);}}finally{c.decache(member);}}return out;} }
